import { Search } from "lucide-react";
import { Profiles } from "@/types/profiles.types";

interface HeaderHomeProps {
    profile: Profiles | null;
}

export default function HeaderHome({ profile }: HeaderHomeProps){
    const title = profile?.gender === "female" ? "Cheffe" : "Chef";

    return (
        <header className="main-header">
            <div className="header-text">
                <p className="welcome-msg">Bonjour, {title} </p>
                <h2 className="main-title">Que cuisinez-vous ?</h2>
            </div>
            <button className="circle-btn">
                <Search size={20} />
            </button>
        </header>
    )
}

"use client";

import TextInput from "@/components/ui/TextInput";

interface IngredientFormProps {
    ingredientName: string;
    setIngredientName: (name: string) => void;
    quantity: string;
    setQuantity: (qty: string) => void;
    scanning: boolean;
    isLoading: boolean;
    error: string | null;
    onStartScanner: () => void;
    onStopScanner: () => void;
}

export default function IngredientForm({
    ingredientName,
    setIngredientName,
    quantity,
    setQuantity,
    scanning,
    isLoading,
    error,
    onStartScanner,
    onStopScanner,
}: IngredientFormProps) {

    return (
        <div className="ingredient-form">
            <div className="input-group">
                <label className="field-label">Nom</label>
                {ingredientName
                    ? <span className="ingredient-badge">{ingredientName}</span>
                    : <span className="ingredient-placeholder">Scanner un ingrédient</span>
                }
            </div>

            <TextInput
                label="Quantité"
                value={quantity}
                onChange={setQuantity}
                placeholder="Ex: 200g"
            />

            {isLoading && <p>Chargement des infos...</p>}
            {error && <p style={{ color: "red" }}>{error}</p>}

            {!scanning ? (
                <button type="button" className="btn-add-item" onClick={onStartScanner}>
                    Scanner un code-barres
                </button>
            ) : (
                <button type="button" className="btn-add-item" onClick={onStopScanner}>
                    Arrêter le scan
                </button>
            )}

            <div id="reader" style={{ width: "100%", minHeight: scanning ? "250px" : "0" }}></div>
        </div>
    );
}

